save(142,dict(paragraphs=["A literary critic and author, Raj has worked across editorial practice and support for fellow writers through Literia Insight and The Literary Mirror. Public literary records identify him as Nitish Raj, the name used in his supplied biography. NIT Jalandhar's creative-writing course programme lists him as the author of Love in Modern Times and a resource person for its January 2024 course.","His poem ‘Miraculous Tone’ centres on the consolation of hearing a beloved voice. Repeated questions carry the speaker between remembered closeness and the wish to feel wanted again. The telephone conversation becomes an intimate space in which sound can briefly reach across absence."],sources=[source('NIT Jalandhar — January 2024 creative-writing course','https://v1.nitj.ac.in/nitj_files/links/Brochure_STC_060923_39772.pdf',['Nitish Raj identified with Literia Insight','Author of Love in Modern Times','Listed course resource person']),source('The Literary Mirror — March 2021 issue','https://theliterarymirror.in/wp-content/uploads/2021/09/The-Literary-Mirror-March-Edition.pdf',['Masthead names Nitish Raj as editor-in-chief','Love in Modern Times title and authorship'],access='search_index_excerpt')],books=[dict(title='Love in Modern Times',detail='Fiction. Authorship confirmed in NIT Jalandhar’s creative-writing programme.',url='https://v1.nitj.ac.in/nitj_files/links/Brochure_STC_060923_39772.pdf')],identity_match='Captured heading Nisith Raj conflicts with supplied biography Nitish Raj. Distinctive paired affiliations Literia Insight and The Literary Mirror match public records under Nitish Raj; original heading preserved pending editor correction.',poems_read=[dict(id=121,title='Miraculous Tone',basis='Full original English poem read, including repeated refrain/questions, phone voice and longing; captured stray markup and diction untouched.')],limitations=['Preferred display spelling requires author/editor confirmation; no silent change to Nisith Raj heading.','Literary Mirror PDF direct request returned 406; only indexed masthead/book evidence used.','Course programme confirms listing, not attendance or an ongoing appointment.','No TEDx, awards or other institutional speaking claims added.'],research_leads=[],next_action='Resolve Nisith/Nitish display spelling with editor; independently review narrative and source links.'))
